document.addEventListener("DOMContentLoaded", function () {
    // Handler Klik Tombol Scan QR Berdasarkan Hari Acara
    document.querySelectorAll(".btn-scan-qr").forEach(btn => {
        btn.addEventListener("click", function (e) {
            const status = this.getAttribute("data-status");
            const title = this.getAttribute("data-title") || "Kegiatan";
            const date = this.getAttribute("data-date") || "";

            if (status === "sebelum") {
                e.preventDefault();
                Swal.fire({
                    title: "Presensi Belum Dibuka",
                    html: `Presensi barcode untuk kegiatan <b>"${title}"</b> hanya bisa dimulai pada hari pelaksanaan acara (<b>${date}</b>).<br><br><span style="color:#64748b; font-size:13px;">Silakan akses kembali saat hari acara tiba.</span>`,
                    icon: "info",
                    iconColor: "#0284c7",
                    confirmButtonColor: "#0284c7",
                    confirmButtonText: "Mengerti",
                    background: "#ffffff",
                    customClass: {
                        popup: "rounded-[28px]",
                        confirmButton: "rounded-xl font-bold px-6 py-2.5"
                    }
                });
            } else if (status === "setelah") {
                e.preventDefault();
                Swal.fire({
                    title: "Presensi Sudah Berakhir",
                    html: `Kegiatan <b>"${title}"</b> telah selesai dilaksanakan pada <b>${date}</b>.<br><br><span style="color:#e11d48; font-size:13px; font-weight:600;">⚠️ Peringatan: Anda sudah tidak bisa melakukan absensi untuk kegiatan ini.</span>`,
                    icon: "warning",
                    iconColor: "#e11d48",
                    confirmButtonColor: "#64748b",
                    confirmButtonText: "Tutup",
                    background: "#ffffff",
                    customClass: {
                        popup: "rounded-[28px]",
                        confirmButton: "rounded-xl font-bold px-6 py-2.5"
                    }
                });
            }
        });
    });

    // Form Broadcast
    document.querySelectorAll(".form-broadcast").forEach(form => {
        form.addEventListener("submit", function (e) {
            e.preventDefault();
            Swal.fire({
                title: "Broadcast Email?",
                text: "Email notifikasi kehadiran akan dikirimkan ke seluruh pengurus OSIS.",
                icon: "question",
                iconColor: "#d97706",
                showCancelButton: true,
                confirmButtonColor: "#d97706",
                cancelButtonColor: "#64748b",
                confirmButtonText: "Ya, Kirim!",
                cancelButtonText: "Batal",
                background: "#ffffff",
                customClass: {
                    popup: "rounded-[24px]",
                    confirmButton: "rounded-xl font-bold px-4 py-2",
                    cancelButton: "rounded-xl font-medium px-4 py-2"
                }
            }).then(result => {
                if (result.isConfirmed) form.submit();
            });
        });
    });

    // Form Hapus
    document.querySelectorAll(".form-delete").forEach(form => {
        form.addEventListener("submit", function (e) {
            e.preventDefault();
            Swal.fire({
                title: "Apakah Anda yakin?",
                text: "Data event dan rekap absensi yang dihapus tidak dapat dikembalikan!",
                icon: "warning",
                iconColor: "#e11d48",
                showCancelButton: true,
                confirmButtonColor: "#e11d48",
                cancelButtonColor: "#64748b",
                confirmButtonText: "Ya, Hapus!",
                cancelButtonText: "Batal",
                background: "#ffffff",
                customClass: {
                    popup: "rounded-[24px]",
                    confirmButton: "rounded-xl font-bold px-4 py-2",
                    cancelButton: "rounded-xl font-medium px-4 py-2"
                }
            }).then(result => {
                if (result.isConfirmed) form.submit();
            });
        });
    });
});
